<script setup>
import {ref,shallowRef,computed,watch,onMounted,onBeforeUnmount} from 'vue'
import * as THREE from 'three'
import {GLTFLoader} from 'three/addons/loaders/GLTFLoader.js'
import {VRMLoaderPlugin,VRMUtils} from '@pixiv/three-vrm'
import SkeletonStage from './SkeletonStage.vue'
import {parseBVH} from './bvh.mjs'
import {createReplayExperiment} from '../motion/replay-experiment.mjs'
import {assessReplaySegment} from '../motion/segment-assessment.mjs'
import {applyPoseRecord} from '../motion/motion-record.mjs'
const host=ref(null),bvh=shallowRef(null),time=ref(0),playing=ref(false),speed=ref(1),rootMode=ref('height'),retargetMode=ref('direction'),blendWeight=ref(1),constraints=ref(false),physics=ref(false),stage=ref('final'),yaw=ref(0),error=ref(''),status=ref('正在读取本机角色和舞蹈…'),result=shallowRef(null),profile=shallowRef(null),record=ref(''),showRecord=ref(false),evaluationMs=ref(0),assessmentStart=ref(9),assessmentEnd=ref(18),assessing=ref(false),assessmentProgress=ref(''),assessment=shallowRef(null)
const duration=computed(()=>bvh.value?.duration||0),stages={retarget:'重定向',blend:'混合',constrained:'约束',final:'最终'}
const pretty=value=>JSON.stringify(value,null,2)
const metric=(value,scale=1)=>Number.isFinite(value)?(value*scale).toFixed(3):'—'
let renderer,scene,camera,vrm,experiment,observer,ticker,lastNow=0,disposed=false,blobUrl,assessmentAbort
function render(){if(!renderer||!vrm)return;const angle=yaw.value*Math.PI/180;const hips=vrm.humanoid?.getNormalizedBoneNode('hips')||vrm.humanoid?.getRawBoneNode('hips');vrm.scene.updateMatrixWorld(true);const root=hips?.getWorldPosition(new THREE.Vector3())||new THREE.Vector3();camera.position.set(root.x+Math.sin(angle)*4,1,root.z+Math.cos(angle)*4);camera.lookAt(root.x,1,root.z);renderer.render(scene,camera)}
function resize(){if(!renderer||!host.value)return;const {width,height}=host.value.getBoundingClientRect();if(!width||!height)return;renderer.setSize(width,height);const aspect=width/height;camera.left=-1.25*aspect;camera.right=1.25*aspect;camera.top=1.15;camera.bottom=-1.15;camera.updateProjectionMatrix();render()}
function evaluate(dt=0){if(!experiment||disposed||assessing.value)return;try{const started=performance.now();const next=experiment.evaluate({time:time.value,rootMode:rootMode.value,retargetMode:retargetMode.value,blendWeight:blendWeight.value,constraints:constraints.value,physics:physics.value,dt});evaluationMs.value=performance.now()-started;result.value=next;if(stage.value!=='final'){applyPoseRecord(vrm,next.trace[stage.value]);vrm.update(0)}render()}catch(e){playing.value=false;error.value=e.message}}
function seek(value){playing.value=false;time.value=Math.max(0,Math.min(duration.value,Number(value)));vrm?.springBoneManager?.reset();evaluate()}
function step(direction){seek(time.value+direction*(bvh.value?.frameTime||1/30))}
function tick(now){const elapsed=lastNow?Math.min((now-lastNow)/1000,.1):0;lastNow=now;if(playing.value&&experiment&&!assessing.value){const dt=elapsed*speed.value;time.value+=dt;if(time.value>duration.value){time.value=0;vrm?.springBoneManager?.reset()}evaluate(dt)}ticker=requestAnimationFrame(tick)}
function keydown(event){if(assessing.value)return;if(['INPUT','SELECT','TEXTAREA','BUTTON'].includes(event.target.tagName))return;if(event.code==='Space'){event.preventDefault();playing.value=!playing.value}if(event.code==='ArrowLeft'){event.preventDefault();step(-1)}if(event.code==='ArrowRight'){event.preventDefault();step(1)}}
async function assess(){
 if(!experiment||assessing.value)return;playing.value=false;assessment.value=null;error.value='';assessing.value=true;assessmentAbort=new AbortController();const saved=time.value;
 try{assessment.value=await assessReplaySegment(experiment,{start:Number(assessmentStart.value),end:Number(assessmentEnd.value),frameTime:bvh.value.frameTime,rootMode:rootMode.value,signal:assessmentAbort.signal,onProgress:p=>{assessmentProgress.value=`${p.label} · ${p.done} / ${p.total}`}})}catch(e){if(e.name!=='AbortError')error.value=e.message;else assessmentProgress.value='已取消'}finally{assessing.value=false;if(!disposed){time.value=saved;evaluate()}}
}
function inspectPeak(row){const peak=row.motion.final.angularSpeed.worst;if(!peak)return;rootMode.value=row.options.rootMode;retargetMode.value=row.options.retargetMode;constraints.value=row.options.constraints;blendWeight.value=1;physics.value=false;seek(peak.time)}
function inspect(){playing.value=false;record.value=pretty(result.value?.trace||{});showRecord.value=true}
watch([rootMode,retargetMode,blendWeight,constraints,physics,stage],()=>{vrm?.springBoneManager?.reset();evaluate()});watch(yaw,render)
onMounted(async()=>{ticker=requestAnimationFrame(tick);document.addEventListener('keydown',keydown);try{
 const [avatar,reference]=await Promise.all([window.komorebi.motionAvatar(),window.komorebi.motionReference()]);if(disposed)return;if(!avatar?.bytes)throw Error('本机未找到研究用 VRM 角色。');if(!reference?.text)throw Error('本机未安装研究用 BVH 参考。');bvh.value=parseBVH(reference.text)
 renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});renderer.setPixelRatio(devicePixelRatio);renderer.outputColorSpace=THREE.SRGBColorSpace;host.value.append(renderer.domElement);scene=new THREE.Scene();camera=new THREE.OrthographicCamera(-1,1,1.15,-1.15,.1,30);scene.add(new THREE.HemisphereLight(0xffffff,0xabb5c5,2));const light=new THREE.DirectionalLight(0xffffff,2);light.position.set(1,3,3);scene.add(light);scene.add(new THREE.GridHelper(4,16,0xcbd4dd,0xe0e6ed));blobUrl=URL.createObjectURL(new Blob([avatar.bytes],{type:'model/gltf-binary'}));const loader=new GLTFLoader();loader.register(parser=>new VRMLoaderPlugin(parser));const gltf=await loader.loadAsync(blobUrl);URL.revokeObjectURL(blobUrl);blobUrl=null;vrm=gltf.userData.vrm;if(!vrm)throw Error('角色文件未包含 VRM 人体骨架。');if(disposed){VRMUtils.deepDispose(vrm.scene);return}VRMUtils.rotateVRM0(vrm);scene.add(vrm.scene);vrm.scene.updateMatrixWorld(true);experiment=createReplayExperiment(vrm,bvh.value);profile.value=experiment.profile;status.value='';observer=new ResizeObserver(resize);observer.observe(host.value);evaluate();resize()
 }catch(e){if(!disposed){status.value='';error.value=e.message}}})
onBeforeUnmount(()=>{disposed=true;assessmentAbort?.abort();cancelAnimationFrame(ticker);document.removeEventListener('keydown',keydown);observer?.disconnect();experiment?.dispose?.();if(blobUrl)URL.revokeObjectURL(blobUrl);if(scene)VRMUtils.deepDispose(scene);renderer?.dispose();renderer?.domElement.remove()})
</script>
<template>
 <div class="replay-study">
  <p v-if="error" class="study-error" role="alert">{{error}}</p><p v-if="status" role="status">{{status}}</p>
  <div class="retarget-layout">
   <section class="study-preview"><div class="preview-label">源人体骨架 · BVH / 同一时间轴</div><SkeletonStage v-if="bvh" :bvh="bvh" :time="time"/><p class="preview-note">源记录属于原始骨架；只用作对照，不应用到目标角色。</p></section>
   <section class="study-preview"><div class="preview-label">目标 VRM · {{stages[stage]}}</div><div class="vrm-stage"><div ref="host" class="vrm-canvas" aria-label="分层回放目标角色"/><label>观察角度 <input v-model.number="yaw" type="range" min="-180" max="180"/></label></div><p class="preview-note">当前帧 {{Math.round((result?.trace?.time||0)/(bvh?.frameTime||1/30))}} · 只读研究窗口</p></section>
   <section class="study-detail retarget-detail"><h2>逐层看动作如何变化。</h2><p>同一源动作、同一时钟。默认只保留根高度，混合权重 1，关闭约束与物理，建立可重复的基线。混合权重控制与角色静止姿态（rest）的混合，并非日常动作拼接器。</p>
    <fieldset :disabled="assessing" class="assessment-controls"><div class="retarget-controls"><label>显示层 <select v-model="stage"><option v-for="(label,key) in stages" :key="key" :value="key">{{label}}</option></select></label><label>映射方式 <select v-model="retargetMode" aria-label="旋转映射方式"><option value="direction">方向映射 · 原基线</option><option value="rotation" :disabled="profile?.retargetModes?.rotation===false">校准旋转 · 保留旋转变化</option></select></label><label>根位移 <select v-model="rootMode"><option value="height">只保留高度</option><option value="source">保留源轨迹</option><option value="balance">去场景移动，保留平衡</option></select></label><label>混合权重 <input v-model.number="blendWeight" type="range" min="0" max="1" step=".01"/>{{blendWeight.toFixed(2)}}</label><label><input v-model="constraints" type="checkbox"/>关节约束</label><label><input v-model="physics" type="checkbox"/>头发与衣物物理</label></div></fieldset>
    <p>以下数值描述每层的姿态变化；变化幅度大并不直接说明动作有误。物理按固定步长从源起点重建，长距离定位可能需要等待。镜头仅跟随根位置，不改动根轨迹。</p>
    <p class="study-proof">实际采样 {{metric(result?.trace?.time)}}s · 本次计算 {{evaluationMs.toFixed(1)}}ms</p><p class="study-proof">源方向最大夹角 {{metric(result?.sourceDirectionsError?.maxRadians,180/Math.PI)}}° · {{result?.sourceDirectionsError?.scope}}</p><h3>源旋转变化保留</h3><p>相对首帧校准参考的最大朝向残差 {{metric(result?.trace?.rotationResidual?.maxRadians,180/Math.PI)}}° · 可定义骨轴的扭转分量 {{metric(result?.trace?.rotationResidual?.maxTwistRadians,180/Math.PI)}}°。</p><p class="study-proof">残差只针对声明的校准参考，不是人体解剖或蒙皮质量分。首帧绝对扭转未知；没有旋转通道时不启用新模式。</p><div class="study-markers"><button @click="seek(12.533)">12.533s 上臂</button><button @click="seek(23.5)">23.5s 手腕</button><button @click="seek(41.8)">41.8s 足趾</button></div><details><summary>各骨源旋转残差与映射覆盖</summary><pre>{{pretty(result?.trace?.rotationResidual)}}</pre></details>
    <section class="segment-assessment" aria-label="完整段落评估">
     <h3>完整段落对照</h3><p class="study-proof">相同源时间，固定混合1、物理关闭，比较方向基线、校准旋转、旋转加足约束。数值用于定位异常候选，不生成自然度评分。</p>
     <label>开始 / 秒 <input type="number" v-model.number="assessmentStart" min="0" :max="duration" :disabled="assessing" step=".1" aria-label="段落开始秒"/></label><label>结束 / 秒 <input type="number" v-model.number="assessmentEnd" min="0" :max="duration" :disabled="assessing" step=".1" aria-label="段落结束秒"/></label>
     <button :disabled="!result||assessing" @click="assess">评估完整段落</button><button v-if="assessing" @click="assessmentAbort?.abort()">取消评估</button><p role="status">{{assessmentProgress}}</p>
     <div v-if="assessment" class="assessment-results"><p>实际区间 {{metric(assessment.actual.start)}}–{{metric(assessment.actual.end)}} 秒 · 每条件 {{assessment.actual.count}} 帧。</p>
      <table class="change-table"><thead><tr><th>条件</th><th>最终方向P95 °</th><th>最终校准残差P95 °</th><th>最终角速率P95 °/s</th><th>约束角改写P95 °</th><th>最大速率候选</th></tr></thead><tbody><tr v-for="row in assessment.rows" :key="row.label"><th>{{row.label}}</th><td>{{metric(row.mapping.directionFinal.p95,180/Math.PI)}}</td><td>{{metric(row.mapping.orientationFinal.p95,180/Math.PI)}}</td><td>{{metric(row.motion.final.angularSpeed.p95,180/Math.PI)}}</td><td>{{metric(row.constraint.angular.p95,180/Math.PI)}}</td><td><button @click="inspectPeak(row)">{{metric(row.motion.final.angularSpeed.worst?.time)}}s · {{row.motion.final.angularSpeed.worst?.joint}}</button></td></tr></tbody></table>
      <details><summary>连续性、约束改写与时间候选</summary><pre>{{pretty(assessment)}}</pre></details><p class="study-proof">角速率变化是标量速率之差，不是角加速度向量；位置为normalized局部米。阈值只标候选。表中为最终层，详细记录另含约束前残差；此对照未运行日常短步拼接器，也未衡量蒙皮与舞蹈表达。</p>
     </div>
    </section>
    <h3>当前帧 · 层间最大变化</h3><table class="change-table"><thead><tr><th>层</th><th>角度 °</th><th>位置 m</th><th>根变化 m</th></tr></thead><tbody><tr v-for="key in ['blend','constrained','final']" :key="key"><th>{{stages[key]}}</th><td>{{metric(result?.changes?.[key]?.maxAngular,180/Math.PI)}}</td><td>{{metric(result?.changes?.[key]?.maxPosition)}}</td><td>{{metric(result?.changes?.[key]?.rootPosition)}}</td></tr></tbody></table><p class="study-proof">最终层差异只测标准人体骨骼，不衡量头发与衣物的次级动画。角度已由弧度转为度，位移单位为米。</p><table class="change-table"><thead><tr><th>层</th><th>根位置 x / y / z（m）</th></tr></thead><tbody><tr v-for="(label,key) in stages" :key="key"><th>{{label}}</th><td>{{result?.trace?.[key]?.root?.position?.map(v=>metric(v)).join(' / ')||'—'}}</td></tr></tbody></table><p class="study-proof">根位置为标准骨架本地绝对坐标，保留真实轨迹；镜头跟随不会归零这些数值。各关节的完整数值见当前帧记录。</p>
    <details><summary>身体能力与可选骨骼</summary><pre>{{pretty(profile||{})}}</pre></details>
    <button :disabled="!result||assessing" @click="inspect">查看当前帧记录 / 手动复制</button>
    <div v-if="showRecord"><p>记录已冻结。点击文本后全选并手动复制。</p><textarea readonly :value="record" aria-label="当前帧 motion trace JSON" @focus="$event.target.select()"/></div>
    <p class="reference-license">本机 VRM 与 BVH 派生轨迹仅在内存中生成，不上传或自动导出。舞蹈参考 CC BY-NC 4.0；角色 © Jessair，不随源码或应用包提供。</p>
   </section>
  </div>
  <footer class="study-transport"><button :disabled="!result||assessing" @click="playing=!playing">{{playing?'暂停':'播放'}}</button><button :disabled="!result||assessing" @click="step(-1)">← 帧</button><button :disabled="!result||assessing" @click="step(1)">帧 →</button><span class="study-time">{{(result?.trace?.time||0).toFixed(2)}} / {{duration.toFixed(2)}}s</span><input type="range" min="0" :max="duration" step=".001" :value="time" :disabled="!result||assessing" @input="seek($event.target.value)" aria-label="分层回放时间轴"/><div class="study-speed" role="group" aria-label="分层回放速度"><button v-for="rate in [.1,.25,.5,1]" :key="rate" :class="{chosen:speed===rate}" :aria-pressed="speed===rate" @click="speed=rate">{{rate}}×</button></div></footer>
 </div>
</template>
<style scoped>
.assessment-controls{border:0;padding:0;margin:0}.segment-assessment input[type=number]{width:65px;margin:5px}.assessment-results{overflow-x:auto}.replay-study{display:flex;flex:1;min-height:0;flex-direction:column}.replay-study h3{font-size:11px;margin:16px 0 6px}.replay-study pre{white-space:pre-wrap;overflow-wrap:anywhere;font:10px/1.65 ui-monospace,monospace;color:#5b7187;background:#edf1f5;padding:10px;border-radius:6px;max-height:190px;overflow:auto}.replay-study details{margin:10px 0;font-size:11px}.replay-study summary{cursor:pointer}.replay-study textarea{width:100%;height:180px;resize:vertical;font:10px/1.5 ui-monospace,monospace;border:1px solid #d5dfe9;border-radius:6px;padding:8px;color:#435e76;background:#fff}.change-table{width:100%;border-collapse:collapse;font:10px/1.8 ui-monospace,monospace}.change-table th,.change-table td{text-align:left;padding:6px;border-bottom:1px solid #dce3eb}.change-table th{font-weight:500}.replay-study button:disabled{opacity:.45;cursor:default}
</style>
